import React from 'react';
import './Sidebar.css';
import { Link } from 'react-router-dom'; // Link bileşenini içe aktar


function Sidebar() {
  return (
    <aside className="sidebar">
      <h2>BeeonHive</h2>
      <nav>
        <ul>
          <li>
            <Link to="/admin" className="sidebar-link">Admin Paneli</Link>
          </li>
          <li>Ürünlere Göz At</li>
          <li>İletişim</li>
          <li>Çıkış Yap</li>
        </ul>
      </nav>
    </aside>
  );
}

export default Sidebar
